// Verb trainer data (src/lessons/it/verbs.ts is generated by scripts/build_verbs.py).

export type TenseId = 'presente' | 'passato' | 'futuro' | 'imperfetto' | 'condizionale' | 'imperativo';

export type VerbGroup = 'are' | 'ere' | 'ire' | 'isc' | 'irregular' | 'modal' | 'reflexive';

export interface Verb {
  inf: string;
  ru: string;
  az: string;
  group: VerbGroup;
  /**
   * Per tense, the forms for io, tu, lui/lei, noi, voi, loro. Each cell lists every correct
   * form, the main one first (masculine before feminine: "sono andato", "sono andata").
   * An empty cell has no form (the imperative has only tu, noi, voi here).
   */
  forms: Record<TenseId, string[][]>;
}
